bus = EventBus(); log = []
def evil(n, p): raise SystemExit(1)
def good(n, p): log.append('delivered')
bus.subscribe('http.*', evil)
bus.subscribe('http.*', good)
try:
    bus.publish('http.request', {'path': '/'})
except SystemExit:
    pass
assert log == ['delivered']  # likely fails if only `except Exception` used

bus = EventBus(); order = []
def reentrant(n, p):
    if p.get('depth', 0) < 1:
        bus.publish('sql.active_record', {'depth': 1})  # reentrant
    order.append(('reentrant', p.get('depth', 0)))
def normal(n, p): order.append(('normal', p.get('depth', 0)))
bus.subscribe('sql.*', reentrant)
bus.subscribe('sql.*', normal)
bus.publish('sql.active_record', {'depth': 0})
# subscription order must be preserved at each publish level

def bad_subscriber(n, p): raise ValueError('subscriber failed')
def good_subscriber(n, p): delivered.append(True)
delivered = []
class FailingSink:
    def report(self, exc): raise RuntimeError('sink broken')
bus = EventBus(observability_sink=FailingSink())
bus.subscribe('http.*', bad_subscriber)
bus.subscribe('http.*', good_subscriber)
bus.publish('http.request', {'path': '/'})
assert delivered == [True]  # good_subscriber must still receive event

bus = EventBus(); snapshots = []
payload = {'count': 0}
def recorder(n, p): snapshots.append(dict(p))
def mutator(n, p): p['count'] += 1  # mutation attempt
bus.subscribe('app.*', mutator)
bus.subscribe('app.*', recorder)
bus.publish('app.tick', payload)
bus.publish('app.tick', payload)
# snapshots[0] and snapshots[1] must both show {'count': 0}
assert snapshots == [{'count': 0}, {'count': 0}], f'leaked mutation: {snapshots}'
